## 合约开发

### Solidity 合约示例

```solidity
pragma solidity ^0.4.25;

contract CredentialManager {
    struct Credential {
        string credId;
        address holder;
        uint256 amount;
        bool exists;
    }

    mapping(string => Credential) public credentials;

    function issue(string credId, address holder, uint256 amount) public {
        require(!credentials[credId].exists, "Credential already exists");
        credentials[credId] = Credential(credId, holder, amount, true);
    }

    function transfer(string credId, address newHolder) public {
        require(credentials[credId].exists, "Credential not found");
        credentials[credId].holder = newHolder;
    }
}
```

